// Workspace members inside the project are first-party code: they are skipped like
// the project root. Local dependencies outside the project stay uncheckable.
// Fixtures under fixtures/workspaces were generated by npm 10, bun 1.4 and uv.
use serde_json::{json, Value};
use std::{fs, path::Path, process::Command};
use vorda::{
    scanner::feeds::{KEV, OSV},
    store::{identity, now},
};

const DEAD: &str = "http://127.0.0.1:9";

fn copy(from: &Path, to: &Path) {
    fs::create_dir_all(to).unwrap();
    for entry in fs::read_dir(from).unwrap() {
        let entry = entry.unwrap();
        let target = to.join(entry.file_name());
        if entry.file_type().unwrap().is_dir() {
            copy(&entry.path(), &target);
        } else {
            fs::copy(entry.path(), target).unwrap();
        }
    }
}

fn project(temp: &Path, fixture: &str) -> std::path::PathBuf {
    let root = temp.join("project");
    copy(
        &Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests/fixtures/workspaces")
            .join(fixture),
        &root,
    );
    root
}

fn packages(data: &Value) -> Vec<String> {
    let mut list: Vec<String> = data["packages"]
        .as_array()
        .unwrap()
        .iter()
        .map(|p| {
            format!(
                "{}:{}@{}",
                p["ecosystem"].as_str().unwrap(),
                p["name"].as_str().unwrap(),
                p["version"].as_str().unwrap()
            )
        })
        .collect();
    list.sort();
    list
}

fn inventory(fixture: &str) -> (i32, Value) {
    let temp = tempfile::tempdir().unwrap();
    let root = project(temp.path(), fixture);
    let output = Command::new(env!("CARGO_BIN_EXE_vorda"))
        .arg("--state")
        .arg(temp.path().join("state"))
        .args(["inventory", "--root"])
        .arg(&root)
        .output()
        .unwrap();
    (
        output.status.code().unwrap(),
        serde_json::from_slice(&output.stdout).unwrap(),
    )
}

/// Scan with every feed answer served from a fresh synthetic cache behind a dead
/// proxy: one package, optionally with one advisory.
fn scan(
    root: &Path,
    state: &Path,
    package: (&str, &str, &str),
    advisory: Option<&str>,
) -> (i32, Value) {
    let (ecosystem, name, version) = package;
    let cache = state.join("cache");
    fs::create_dir_all(&cache).unwrap();
    let mut rows = vec![
        (
            json!([KEV, null]),
            KEV.to_string(),
            json!({"vulnerabilities":[]}),
        ),
        (
            json!([format!("{OSV}/querybatch"), {"queries":[{"package":{"name":name,"ecosystem":ecosystem},"version":version}]}]),
            format!("{OSV}/querybatch"),
            json!({"results":[advisory.map_or(json!({}), |id| json!({"vulns":[{"id":id}]}))]}),
        ),
    ];
    if let Some(id) = advisory {
        rows.push((
            json!([format!("{OSV}/vulns/{id}"), null, [[ecosystem, name]]]),
            format!("{OSV}/vulns/{id}"),
            json!({"id":id,"summary":"Synthetic workspace finding","affected":[{"package":{"name":name,"ecosystem":ecosystem},"versions":[version]}]}),
        ));
    }
    for (key, url, data) in rows {
        fs::write(
            cache.join(format!("{}.json", identity(&key).unwrap())),
            json!({"source_url":url,"checked":now(),"fetched_at":"fixture","data":data})
                .to_string(),
        )
        .unwrap();
    }
    let mut command = Command::new(env!("CARGO_BIN_EXE_vorda"));
    command.env("VORDA_ADVISORIES", "online");
    command
        .arg("--state")
        .arg(state)
        .args(["scan", "--json", "--root"])
        .arg(root);
    for var in [
        "HTTPS_PROXY",
        "https_proxy",
        "HTTP_PROXY",
        "http_proxy",
        "ALL_PROXY",
        "all_proxy",
    ] {
        command.env(var, DEAD);
    }
    let output = command
        .env("NO_PROXY", "")
        .env("no_proxy", "")
        .output()
        .unwrap();
    (
        output.status.code().unwrap(),
        serde_json::from_slice(&output.stdout).unwrap(),
    )
}

fn scan_fixture(fixture: &str, version: &str, advisory: Option<&str>) -> (i32, Value) {
    let temp = tempfile::tempdir().unwrap();
    let root = project(temp.path(), fixture);
    scan(
        &root,
        &temp.path().join("state"),
        ("npm", "lodash", version),
        advisory,
    )
}

#[test]
fn healthy_npm_and_bun_workspaces_are_clean() {
    for tool in ["npm", "bun"] {
        let fixture = format!("{tool}-healthy");
        let (code, data) = inventory(&fixture);
        assert_eq!(code, 0, "{fixture}: {data}");
        assert_eq!(data["status"], "complete", "{data}");
        assert_eq!(packages(&data), ["npm:lodash@4.17.21"], "{data}");
        let (code, data) = scan_fixture(&fixture, "4.17.21", None);
        assert_eq!(code, 0, "{fixture}: {data}");
        assert_eq!(data["status"], "no-known-findings", "{data}");
        assert_eq!(data["errors"], json!([]), "{data}");
    }
}

#[test]
fn a_vulnerable_registry_package_in_a_workspace_is_still_reported() {
    for tool in ["npm", "bun"] {
        let fixture = format!("{tool}-vulnerable");
        let (code, data) = scan_fixture(&fixture, "4.17.20", Some("GHSA-fixture-workspace"));
        assert_eq!(code, 3, "{fixture}: {data}");
        assert_eq!(data["errors"], json!([]), "{data}");
        assert!(
            data["findings"]
                .as_array()
                .unwrap()
                .iter()
                .any(|f| f["advisory"] == "GHSA-fixture-workspace"
                    && f["package"]["name"] == "lodash"),
            "{data}"
        );
    }
}

#[test]
fn a_local_dependency_outside_the_project_stays_unknown() {
    for (fixture, named) in [
        ("npm-outside", "../outside"),
        ("bun-outside", "outside-lib"),
        ("uv-outside", "outside-lib"),
    ] {
        let (code, data) = inventory(fixture);
        assert_eq!(code, 2, "{fixture}: {data}");
        assert_eq!(data["status"], "unknown", "{data}");
        let expected = if fixture == "uv-outside" {
            "PyPI:six@1.16.0"
        } else {
            "npm:lodash@4.17.21"
        };
        assert_eq!(packages(&data), [expected], "{data}");
        let errors = data["errors"].to_string();
        assert_eq!(data["errors"].as_array().unwrap().len(), 1, "{data}");
        assert!(
            errors.contains("Entry-level") && errors.contains(named),
            "{errors}"
        );
    }
}

#[test]
fn uv_workspace_members_and_roots_are_skipped() {
    for (fixture, expected) in [
        ("uv-workspace", vec!["PyPI:idna@3.4", "PyPI:six@1.16.0"]),
        ("uv-dynamic", vec!["PyPI:six@1.16.0"]),
    ] {
        let (code, data) = inventory(fixture);
        assert_eq!(code, 0, "{fixture}: {data}");
        assert_eq!(data["status"], "complete", "{data}");
        assert_eq!(packages(&data), expected, "{data}");
    }
}

#[test]
fn a_vendored_npm_package_that_is_not_a_member_stays_uncheckable() {
    // `file:./vendor/lodash` beside `workspaces: ["packages/*"]`.
    let (code, data) = inventory("npm-vendored");
    assert_eq!(code, 2, "{data}");
    assert_eq!(data["status"], "unknown", "{data}");
    assert_eq!(
        packages(&data),
        ["npm:lodash@4.18.1", "npm:minimist@1.2.8"],
        "{data}"
    );
    let errors = data["errors"].as_array().unwrap();
    assert_eq!(errors.len(), 1, "{data}");
    assert!(
        errors[0].to_string().contains("Entry-level")
            && errors[0].to_string().contains("vendor/lodash"),
        "{data}"
    );
}

#[test]
fn a_vendored_uv_package_that_is_not_a_member_is_queried() {
    // An editable vendored django is queried by its name and version.
    let (code, data) = inventory("uv-vendored");
    assert_eq!(code, 0, "{data}");
    assert_eq!(data["status"], "complete", "{data}");
    assert_eq!(
        packages(&data),
        ["PyPI:django@2.2.0", "PyPI:six@1.16.0"],
        "{data}"
    );
}

#[test]
fn an_editable_requirement_is_one_uncheckable_entry_beside_checked_pins() {
    let temp = tempfile::tempdir().unwrap();
    let root = temp.path().join("project");
    fs::create_dir(&root).unwrap();
    fs::write(root.join("requirements.txt"), "django==2.2.0\n-e .\n").unwrap();
    let (code, data) = scan(
        &root,
        &temp.path().join("state"),
        ("PyPI", "django", "2.2.0"),
        Some("GHSA-fixture-editable"),
    );
    assert_eq!(code, 3, "{data}");
    assert_eq!(data["status"], "vulnerable", "{data}");
    assert_eq!(packages(&data), ["PyPI:django@2.2.0"], "{data}");
    let errors = data["errors"].as_array().unwrap();
    assert_eq!(errors.len(), 1, "{data}");
    assert!(
        errors[0].to_string().contains("Entry-level") && errors[0].to_string().contains("-e ."),
        "{data}"
    );
    assert!(
        data["findings"]
            .as_array()
            .unwrap()
            .iter()
            .any(|f| f["advisory"] == "GHSA-fixture-editable" && f["package"]["name"] == "django"),
        "{data}"
    );
    // An include still refuses the whole file.
    fs::write(
        root.join("requirements.txt"),
        "django==2.2.0\n-r other.txt\n",
    )
    .unwrap();
    let output = Command::new(env!("CARGO_BIN_EXE_vorda"))
        .arg("--state")
        .arg(temp.path().join("state2"))
        .args(["inventory", "--root"])
        .arg(&root)
        .output()
        .unwrap();
    let data: Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(output.status.code(), Some(2), "{data}");
    assert_eq!(data["packages"], json!([]), "{data}");
    assert!(data["errors"].to_string().contains("File-level"), "{data}");
}
